function compose(d: Def, lang: "it" | "en") {
  const [, , , roleIt, roleEn, taskIt, taskEn, delIt, delEn] = d;
  if (lang === "en") {
    const article = /^[aeiou]/i.test(roleEn) ? "an" : "a";
    return `Act as ${article} ${roleEn}. ${taskEn}\n\nContext: [CONTEXT].\n\nRequirements:\n- Be specific and concrete; avoid generic advice and filler.\n- State assumptions explicitly; never invent facts, data or sources.\n- If essential information is missing, ask up to 3 targeted questions first.\n\nOutput: ${delEn}.\n\nBefore answering, check that every point is accurate, relevant and immediately actionable.`;
  }
  return `Agisci come ${roleIt}. ${taskIt}\n\nContesto: [CONTESTO].\n\nRequisiti:\n- Sii specifico e concreto; evita consigli generici e riempitivi.\n- Dichiara le assunzioni; non inventare fatti, dati o fonti.\n- Se mancano informazioni essenziali, fai prima al massimo 3 domande mirate.\n\nOutput: ${delIt}.\n\nPrima di rispondere, verifica che ogni punto sia accurato, pertinente e subito applicabile.`;
}

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

export const extendedSeedPrompts: SeedPrompt[] = defs.map((d, i) => ({
  category: d[0],
  title: d[1],
  titleEn: d[2],
  description: `${cap(d[7])}.`,
  descriptionEn: `${cap(d[8])}.`,
  content: compose(d, "it"),
  contentEn: compose(d, "en"),
  tags: d[9],
  model: d[10] ?? "Universale",
  featured: i % 9 === 0,
  uses: 0,
}));
